head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onkeyup]<br/>GridView 컴포넌트가 포커스된 상태에서 눌렀던 키보드의 키를 떼면 발생합니다.",
    "validation" : [
        "GridView 컴포넌트가 포커스된 상태에서 눌렀던 키보드의 키를 떼면 발생합니다.",
        "이벤트 객체 e (KeyboardEvent) 가 핸들러에 전달됩니다.",
        "이벤트 핸들러에서 false 값을 반환하면 일부 후속 처리가 중단됩니다.",
        "onkeyup 과 oneditkeyup 는 별개의 이벤트이며 중복으로 발생할 수 있습니다.",
        "oneditkeyup 이벤트는 GridView 가 편집 상태일때 발생하며 onkeyup 이벤트는 GridView 가 포커스된 상태일때 발생합니다.",
        "GridView 가 편집 상태일때 키를 입력하면 onkeydown -> oneditkeydown -> onkeyup -> oneditkeyup 순서로 이벤트가 발생합니다."
    ]
}



//  seq       : 한 번의 키 조작(누름 -> 뗌) 안에서 이벤트 발생 순번
//  cycleDone : 직전 조작이 끝났는지 여부 (다음 누름 이벤트에서 순번을 1 부터 다시 시작)
scwin.gVar = { "seq" : 0, "cycleDone" : true };



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값을 명시 설정한다.
    //  con_returnValue 는 자체 값 셀렉트박스 (미설정 / true / false 순서)
    con_returnValue.setSelectedIndex(0);

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  editable="true" 로 편집 가능한 GridView 를 구성한다.
//  Body Column 4개 (이름 / 코드 / 수량 / 비고) 는 모두 inputType="text" 이며,
//  onkeydown / oneditkeydown / onkeyup / oneditkeyup 4개 이벤트를 모두 등록하여
//  포커스 상태와 편집 상태의 발생 차이 및 발생 순서를 확인한다.
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    scwin.gVar.seq = 0;
    scwin.gVar.cycleDone = true;

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 조작 절차 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 편집 가능(editable=true) GridView 이며 Body Column 은 이름 / 코드 / 수량 / 비고 4개(모두 inputType=text) 입니다. Cell 은 더블클릭하면 편집 상태가 됩니다.\n[옵션] 핸들러 반환값(con_returnValue)은 Target 재생성 없이 즉시 반영됩니다.\n[절차1] con_returnValue 를 미설정으로 두고 코드 Cell 을 한 번만 클릭해 편집 상태가 아닌 채로 방향키(아래 / 위)를 눌렀다 떼어 결과창에 onkeyup 만 출력되는 것을 확인합니다.\n[절차2] 같은 Cell 을 더블클릭해 편집 상태로 만들고 같은 방향키를 눌렀다 떼어 onkeyup 과 oneditkeyup 이 함께 출력되는 것과, 결과창 각 줄 앞 순번으로 네 이벤트의 발생 순서를 확인합니다.\n[절차3] con_returnValue 를 false 로 바꾸고 편집 상태에서 다시 키를 눌렀다 떼어 어떤 후속 처리가 출력되지 않는지 확인한 뒤 미설정 / true 결과와 비교합니다.\n[확인] 결과창 각 줄 앞의 순번은 한 번의 키 조작(누름 - 뗌) 마다 1 부터 다시 시작합니다."', '', 'label1');

    // dataList 생성 (4 Column, 4 Row) - Body Column 순서와 일치
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strData += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strData += '<w2:column id="qty" name="qty" dataType="text"></w2:column>';
    strData += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [
        { "name" : "영업본부", "code" : "코드0", "qty" : "10", "memo" : "비고0" },
        { "name" : "개발본부", "code" : "코드1", "qty" : "20", "memo" : "비고1" },
        { "name" : "관리팀", "code" : "코드2", "qty" : "30", "memo" : "비고2" },
        { "name" : "지원팀", "code" : "코드3", "qty" : "40", "memo" : "비고3" }
    ];
    dlt_bind.setJSON(jsonData, false);

    let properties = {
        dataList : "data:dlt_bind",
        editable : "true"
    };
    let cList = $c.gcm.createCList(properties);

    // 포커스 상태와 편집 상태의 키 입력 이벤트 4개를 모두 등록하여 발생 여부와 순서를 확인한다.
    let eList = $c.gcm.createEList(["onkeydown", "oneditkeydown", "onkeyup", "oneditkeyup"]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:760px;height:220px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol2" value="코드"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="수량"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="code" dataList="code"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="qty" dataList="qty"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 이벤트 발생 순서 출력 공통 함수
//  - 각 핸들러가 발생 즉시 한 줄씩 출력하므로 출력 순서 = 실제 발생 순서
//  - 순번은 키를 누르고 떼는 한 번의 조작(down -> up) 마다 1 부터 다시 시작한다.
scwin.logEvent = function (message, isDown) {
    if (isDown === true && scwin.gVar.cycleDone === true) {
        scwin.gVar.seq = 0;
        scwin.gVar.cycleDone = false;
    }
    if (isDown === false) {
        scwin.gVar.cycleDone = true;
    }
    scwin.gVar.seq++;
    wf_body_bottom.getObj("scwin").setReturnValue("[" + scwin.gVar.seq + "] " + message);
}



// onkeyup : GridView 가 포커스된 상태에서 눌렀던 키를 떼면 발생 (검증 대상)
//  - e 는 표준 DOM KeyboardEvent 이므로 전달 여부만 한 줄로 출력한다.
//  - con_returnValue 로 핸들러 반환값을 제어하여 false 반환 시 중단되는 후속 처리를 확인한다.
scwin.target1_onkeyup = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    scwin.logEvent("onkeyup 발생", false);
    bottom.setReturnValue("e : " + e);

    let ret = con_returnValue.getValue();   // "" (미설정) / "true" / "false"
    bottom.setReturnValue("핸들러 반환값 : " + (ret === "" ? "생략" : ret));

    if (ret === "true") { return true; }
    if (ret === "false") { return false; }
    // 미설정 : return 문 없음
}



// 발생 순서 / 중복 발생 확인용 (onkeydown -> oneditkeydown -> onkeyup -> oneditkeyup)
scwin.target1_onkeydown = function (e) {
    scwin.logEvent("onkeydown 발생", true);
}

scwin.target1_oneditkeydown = function (info) {
    scwin.logEvent("oneditkeydown 발생", true);
}

scwin.target1_oneditkeyup = function (info) {
    scwin.logEvent("oneditkeyup 발생", false);
}
